import IntlMessages from '../utility/intlMessages'
import {
  Container,
  HeaderSubTitle,
  Header,
  HeaderTitle,
  LeftSideLogoContainer,
  LogoImage,
  MainDetails,
  MainDetailsContent,
  Footer,
  LeftSideFooterButton,
  RightSideFooterButton,
  RightSideContainer,
  MainDetailsTitle,
  MainDetailsWrapper,
  PolicyStatus
} from './policyCardStyle'

function PolicyCard ({
  isPolicyActive,
  policyText,
  logo = 'https://placehold.jp/150x150.png',
  leftSideButtonText = 'leftText',
  rightSideFooterButtonText = 'rightText',
  headerSubTitle = 'headerSubTitle',
  headerTitle = 'headerTitle',
  leftSideButtonClickHandler = () => { },
  rightSideButtonClickHandler = () => { },
  mainDetails = []
}) {
  return (
    <Container>
      <LeftSideLogoContainer >
        <LogoImage src={logo} alt='partner' />
      </LeftSideLogoContainer>

      <RightSideContainer>

        <Header>
          <HeaderSubTitle >
            <IntlMessages id={headerSubTitle} />
          </HeaderSubTitle>
          <HeaderTitle>
            <IntlMessages id={headerTitle} />
          </HeaderTitle>
        </Header>

        <PolicyStatus isActive={isPolicyActive}>
          {policyText}
        </PolicyStatus>

        <MainDetails>
          {mainDetails.map(({ title, value }) => {
            return (
              <MainDetailsWrapper key={title}>
                <MainDetailsTitle>
                  <IntlMessages id={title} />
                </MainDetailsTitle>
                <MainDetailsContent>
                  <IntlMessages id={value} />
                </MainDetailsContent>
              </MainDetailsWrapper>
            )
          })}
        </MainDetails>

        <Footer>
          <LeftSideFooterButton
            onClick={leftSideButtonClickHandler}
          >
            <IntlMessages id={leftSideButtonText} />
          </LeftSideFooterButton>
          <RightSideFooterButton
            onClick={rightSideButtonClickHandler}
          >
            <IntlMessages id={rightSideFooterButtonText} />
          </RightSideFooterButton>
        </Footer>

      </RightSideContainer>
    </Container>
  )
}

export default PolicyCard
