import { useEffect, useState } from 'react'
import { useDispatch, useSelector } from 'react-redux'
import { useIntl } from 'react-intl'
import { useHistory } from 'react-router'

import EmptyClaimListCard from '../../components/EmptyClaimList'
import policyActions from '../../redux/policy/actions'
import agencyActions from '../../redux/agency/actions'
import ScrollTagsV2 from '../../components/ScrollTagsV2'
import {
  ClaimTabs,
  setteledClaimsStauses,
  afterDocumentsClaimStatuses
} from '../../constants'
import {
  sanitizeB2CClaimListDetails,
  useRemoveErrorActionsHelper,
  useRemoveLoadingActionsHelper
} from '../../helpers/utility'
import { Center } from '../PolicyList/policyList.style'
import Loader from '../../components/Loader'
import Pagination from '../../components/Pagination'
import { CenterEmpty, ClaimCardListContainer, Wrapper } from './claimList.style'
import ClaimListCard from '../../components/ClaimCard'
import { LANG_STRINGS } from '../../constants/lang'
import { useIsMobile } from '../../hooks/useIsMobile'

function ClaimList ({
  isAgency
}) {
  const dispatch = useDispatch()
  const intl = useIntl()
  const history = useHistory()
  const isMobile = useIsMobile()
  const b2CClaimList = useSelector(state => state.Policy.claimData)
  const agencyClaimList = useSelector(state => state.Agency.agencyClaimList)
  const b2CListMetaData = useSelector(state => state.Policy.metadata)
  const AgencyMetaData = useSelector(state => state.Agency.agencyMetadata)

  // console.log(AgencyMetaData)

  const [selectedTab, setSelectedTab] = useState('')
  const [currPage, setCurrPage] = useState(1)
  const [filteredClaimList, setFilteredClaimList] = useState([])
  const [filteredClaimListMetadata, setFilteredClaimListMetadata] = useState({
    totalRecords: !isAgency ? b2CListMetaData?.total_records : AgencyMetaData?.total_records
  })
  const b2cLoading = useRemoveLoadingActionsHelper(policyActions.GET_CLAIM_LIST_REQUEST)
  const b2CError = useRemoveErrorActionsHelper(policyActions.GET_CLAIM_LIST_REQUEST)
  const agencyLoading = useRemoveLoadingActionsHelper(agencyActions.AGENCY_CLAIM_LIST_REQUEST)
  const agnecyError = useRemoveErrorActionsHelper(agencyActions.AGENCY_CLAIM_LIST_REQUEST)

  const changeClainFilterHandler = (tab) => {
    setCurrPage(1)
    setSelectedTab(tab)
  }

  const currPageHandler = (page) => {
    setCurrPage(page)
    window.scrollTo(0, 0)
  }

  useEffect(() => {
    return () => {
      setFilteredClaimList([])
      setCurrPage(1)
      setSelectedTab('')
    }
  }, [
    isAgency
  ])

  useEffect(() => {
    let query = { page: currPage }

    switch (selectedTab) {
      case 'initiated':
        query.status = 'initiated'
        break
      case 'settled':
        if (Array.isArray(setteledClaimsStauses) && setteledClaimsStauses.length > 0) {
          query.status = setteledClaimsStauses
        } else {
          console.warn('Settled claims statuses are empty or not an array')
        }
        break
      case 'after-documents':
        if (Array.isArray(afterDocumentsClaimStatuses) && afterDocumentsClaimStatuses.length > 0) {
          query.status = afterDocumentsClaimStatuses
        } else {
          console.warn('After Documents statuses are empty or not an array')
        }
        break
      default: query.status = ''
    }

    if (isAgency) {
      dispatch(agencyActions.getAgencyClaimList({ query }))
    } else {
      dispatch(policyActions.getClaimList({ query }))
    }
    return () => {
      dispatch(policyActions.clearPolicyRedux())
      dispatch(agencyActions.resetReduxState())
    }
  }, [
    isAgency,
    currPage,
    selectedTab,
    setteledClaimsStauses
  ])

  const claimList = isAgency ? agencyClaimList : b2CClaimList
  const loading = isAgency ? agencyLoading : b2cLoading
  const claimError = isAgency ? agnecyError : b2CError

  const footerButtonClickHandler = (claimId) => {
    history.push(`/claimdetail/${claimId}`)
  }

  const renderEmptyListCard = () => {
    if (loading || loading === undefined) return null
    if (filteredClaimList?.length) return null
    if (claimError) return <EmptyClaimListCard />
    return (
      <>
        <CenterEmpty>
          <EmptyClaimListCard />
        </CenterEmpty>
      </>
    )
  }

  useEffect(() => {
    setFilteredClaimListMetadata({
      totalRecords: !isAgency ? b2CListMetaData?.total_records : AgencyMetaData?.total_records
    })
    setFilteredClaimList(claimList)
  }, [claimList, selectedTab, currPage, b2CListMetaData, AgencyMetaData, isAgency])

  // console.log("meta data", b2CListMetaData)
  // console.log("filteredClaimListMetadata",filteredClaimListMetadata)

  const tabs = ClaimTabs.map(({ title, filter, mobileTitle }) => ({ title: isMobile ? mobileTitle : title, filter }))
  return (
    <Wrapper>
      <ScrollTagsV2
        tabs={tabs}
        selectedTag={selectedTab}
        onTagClickHandler={changeClainFilterHandler}
      />
      <ClaimCardListContainer>
        {
          loading
            ? <Center>
              <Loader />
            </Center>
            : null
        }
        {
          renderEmptyListCard()}
        {
          Array.isArray(filteredClaimList)
            ? (
              filteredClaimList.map((claim) => {
                const {
                  logo,
                  info,
                  name,
                  productKey,
                  benefitName,
                  claimStatus,
                  footerText,
                  claimStatusText,
                  claimStatusTextColor,
                  claimStatusBackgroundColor,
                  documentFillDate = '',
                  claimInternalId
                } = sanitizeB2CClaimListDetails(claim, intl)
                return (
                  <>
                    <ClaimListCard
                      logo={logo}
                      key={claimInternalId}
                      info={info}
                      title={name}
                      subTitle={productKey}
                      benefitName={benefitName}
                      claimStatus={claimStatus}
                      footerText={footerText}
                      documentFillDate={documentFillDate}
                      claimStatusText={claimStatusText}
                      benefitTitle={LANG_STRINGS.benefitClaimed}
                      claimStatusTextColor={claimStatusTextColor}
                      footerButtonClickHandler={() => footerButtonClickHandler(claimInternalId)}
                      claimStatusBackgroundColor={claimStatusBackgroundColor}
                    />
                  </>
                )
              })
            )
            : null
        }
      </ClaimCardListContainer>
      {
        loading
          ? null
          : <Pagination
            pageSize={9}
            currPage={currPage}
            currPageHandler={currPageHandler}
            totalRecords={Number(filteredClaimListMetadata.totalRecords)}
          />
      }
    </Wrapper>
  )
}

export default ClaimList
