import { ScrollTagsContainer, Tag, Wrapper } from './scrollTags.style'
import IntlMessages from '../utility/intlMessages'

function ScrollTabs ({
  tabs = [],
  selectedTag = '',
  onTagClickHandler = () => {}
}) {
  return (
    <Wrapper>
      <ScrollTagsContainer>
        <div className='tab'>
          {tabs.map(({ title, filter }) => {
            return (
              <Tag key={title} onClick={() => onTagClickHandler(filter)} active={selectedTag === filter}>
                <IntlMessages id={title} />
              </Tag>
            )
          })}
        </div>
      </ScrollTagsContainer>
    </Wrapper>

  )
}

export default ScrollTabs
