import React, { useMemo } from 'react'
import {
  PageTab,
  InfoWrapper,
  PageTabContainer,
  PaginationContainer
} from './pagination.style'
import { RightBlackIcon } from '../../image'
import IntlMessages from '../utility/intlMessages'
import { LANG_STRINGS } from '../../constants/lang'

const Pagination = React.memo(function Component ({
  pageSize = 5,
  currPage = 3,
  totalRecords = 100,
  currWindowAllowed = 5,
  currPageHandler = () => { }
}) {
  const noOfPages = Math.ceil(totalRecords / pageSize)

  const currWindowPageTabs = (pageTabs) => {
    let left = Math.max(Math.min(currPage - Math.floor(currWindowAllowed / 2), noOfPages - currWindowAllowed + 1), 1)
    let right = Math.min(noOfPages, Math.max(currPage + Math.floor(currWindowAllowed / 2), currWindowAllowed))

    while (left <= right) {
      pageTabs.push({
        pageText: left,
        buttonType: 'page'
      })
      left++
    }
  }

  const addFirstTab = (pageTab = []) => {
    if (currPage > currWindowAllowed) {
      pageTab.unshift({
        pageText: 1,
        buttonType: 'page'
      })
    }
  }

  const addNextTab = (pageTabs) => {
    if (noOfPages <= currWindowAllowed) return
    if (currPage > noOfPages - currWindowAllowed + 1) return
    pageTabs.push({
      pageText: '...',
      buttonType: 'next'
    })
  }

  const addLastTab = (pageTabs) => {
    if (currPage < noOfPages - 2 && currPage + currWindowAllowed < noOfPages) {
      pageTabs.push({
        pageText: noOfPages,
        buttonType: 'page'
      })
    }
  }

  const addPrevTab = (pageTab) => {
    if (currPage > 4) {
      pageTab.unshift({
        pageText: '...',
        buttonType: 'prev'
      })
    }
  }

  const addIconTab = (page) => {
    page.push({
      pageText: <img src={RightBlackIcon} alt='last' />,
      buttonType: 'last-icon'
    })
  }

  const pageTabs = useMemo(() => {
    let page = []
    currWindowPageTabs(page)
    addPrevTab(page)
    addFirstTab(page)
    addNextTab(page)
    addLastTab(page)
    addIconTab(page)
    return page
  }, [currPage, totalRecords, pageSize])

  const pageTabClickHandler = (pageText, buttonType) => {
    switch (buttonType) {
      case 'page':
        currPageHandler(pageText)
        break
      case 'last':
        currPageHandler(noOfPages)
        break
      case 'prev':
        currPageHandler(Math.max(currPage - 5, 1))
        break
      case 'next':
        currPageHandler(Math.min(currPage + 5, noOfPages))
        break
      case 'last-icon':
        currPageHandler(noOfPages)
        break
      default:
        currPageHandler(currPage)
        break
    }
  }
  if (!totalRecords) return null

  return (
    <PaginationContainer>
      <InfoWrapper>
        <IntlMessages id={LANG_STRINGS.showing} />
        &nbsp;
        {currPage} / {noOfPages}
      </InfoWrapper>
      <PageTabContainer>
        {pageTabs.map(({ pageText, buttonType }) => {
          return (
            <PageTab
              key={pageText + buttonType}
              onClick={() => pageTabClickHandler(pageText, buttonType)}
              active={pageText === currPage}
            >
              {pageText}
            </PageTab>
          )
        })}
      </PageTabContainer>
    </PaginationContainer>
  )
})

export default Pagination
