import { FormattedMessage } from 'react-intl'
import { LANG_STRINGS } from '../../constants/lang'
import IntlMessages from '../utility/intlMessages'
import {
  BenefitContainer,
  BenefitName,
  BenefitSubTitle,
  ClaimStatus,
  Footer,
  FooterButton,
  Image,
  InfoContainer,
  InfoTitle,
  LeftLogoContainer,
  RightContainer,
  SubTitle,
  Title,
  Wrapper,
  InfoWrapper,
  InfoValue,
  TitleContainer,
  MaxDocSubmissionDate
} from './claimCard.style'

function ClaimListCrad ({
  logo = '',
  subTitle = '',
  title = '',
  benefitTitle = '',
  benefitName = '',
  claimStatus = '',
  footerText = '',
  info = [],
  claimStatusTextColor,
  claimStatusBackgroundColor = '',
  claimStatusText = '',
  documentFillDate = '',
  footerButtonClickHandler = () => {}
}) {
  return (
    <Wrapper>
      <LeftLogoContainer >
        <Image
          src={logo}
        />
      </LeftLogoContainer>
      <RightContainer>

        <TitleContainer>
          <SubTitle>
            <IntlMessages id={subTitle} />
          </SubTitle>
          <Title >
            <IntlMessages id={title} />
          </Title>
        </TitleContainer>

        <BenefitContainer >
          <BenefitSubTitle >
            <IntlMessages id={benefitTitle} />
          </BenefitSubTitle>
          <BenefitName >
            <IntlMessages id={benefitName} />
          </BenefitName>
        </BenefitContainer>

        <ClaimStatus color={claimStatusTextColor} background={claimStatusBackgroundColor}>
          <IntlMessages id={claimStatusText} />
        </ClaimStatus>

        <InfoContainer>
          {
            info.map(({ title, value }) => {
              return (
                <InfoWrapper key={title}>
                  <InfoTitle>
                    <IntlMessages id={title} />
                  </InfoTitle>
                  <InfoValue>
                    <IntlMessages id={value} />
                  </InfoValue>
                </InfoWrapper>
              )
            })
          }
        </InfoContainer>

        {
          documentFillDate
            ? <MaxDocSubmissionDate>
              <FormattedMessage id={LANG_STRINGS.deadline} />
              &nbsp;
              {documentFillDate}
            </MaxDocSubmissionDate>
            : null
        }

        <Footer>
          <FooterButton onClick={footerButtonClickHandler}>
            <IntlMessages id={footerText} />
          </FooterButton>
        </Footer>
      </RightContainer>
    </Wrapper>
  )
}

export default ClaimListCrad
