import { useEffect, useState, useCallback } from 'react'
import get from 'lodash/get'
import { useIntl } from 'react-intl'
import { useDispatch, useSelector } from 'react-redux'

import PolicyCard from '../../components/PolicyCard/policyCard'
import policyActions from '../../redux/policy/actions'
import agencyActions from '../../redux/agency/actions'
import {
  sanitizeAgencyPolicyListDetails,
  sanitizeB2CPolicyListDetails,
  useRemoveErrorActionsHelper,
  useRemoveLoadingActionsHelper
} from '../../helpers/utility'
import { Center, PolicyListContainer, Wrapper } from './policyList.style'
import { LANG_STRINGS } from '../../constants/lang'
import { useHistory } from 'react-router'

import BenefitList from '../BenefitList'
import { AgencyTabs, PolicyTabs, agencyPolicyLink, polisLink } from '../../constants'
import Loader from '../../components/Loader'
import ScrollTabs from '../../components/ScrollTagsV2'
import Pagination from '../../components/Pagination'
import EmptyPolicyClaimListCard from '../../components/EmptyPolicyClaimList'
import { useIsMobile } from '../../hooks/useIsMobile'

function PolicyList ({
  isAgency = false
}) {
  const dispatch = useDispatch()
  const history = useHistory()
  const intl = useIntl()

  const isMobile = useIsMobile()

  const b2CpolicyLoading = useRemoveLoadingActionsHelper(policyActions.POLICY_LIST_REQUEST)
  const agencyPolicyLoading = useRemoveLoadingActionsHelper(agencyActions.AGENCY_POLICY_LIST_REQUEST)
  const b2CpolicyError = useRemoveErrorActionsHelper(policyActions.POLICY_LIST_REQUEST)
  const agencyPolicyError = useRemoveErrorActionsHelper(agencyActions.AGENCY_POLICY_LIST_REQUEST)
  const b2CpolicyList = useSelector((state) => state.Policy.data)
  const agencyPolicyList = useSelector((state) => state.Agency.agencyPolicyList)

  const [isOpenBenefitModal, setIsOpenBenefitModal] = useState(null)

  const policyList = isAgency ? agencyPolicyList : b2CpolicyList
  const b2CpolicyListMetada = useSelector(state => state.Policy.metadata)
  const agencyMetadata = useSelector(state => state.Agency.agencyMetadata)

  const [activePolicyFilter, setActivePolicyFilter] = useState('')
  const [{ page }, setPaginationParams] = useState({
    page: 1
  })

  const isLoading = isAgency ? agencyPolicyLoading : b2CpolicyLoading
  const policyMetaData = isAgency ? agencyMetadata : b2CpolicyListMetada
  const isPolicyListError = isAgency ? agencyPolicyError : b2CpolicyError

  const paginationHandler = useCallback((page) => {
    setPaginationParams({ page })
    window.scrollTo(0, 0)
  }, [])

  const goToPolicyDetailPage = (e, internalId) => {
    e.stopPropagation()
    const source = isAgency ? agencyPolicyLink : polisLink
    history.push(`policydetail/${internalId}?source=${source}`, { isAgency })
  }

  const openBenefitModal = (e, benefitQueryParams) => {
    e.stopPropagation()
    setIsOpenBenefitModal({
      benefitQueryParams: benefitQueryParams
    })
  }

  const closeBenefitModal = () => {
    setIsOpenBenefitModal(null)
  }

  const onFilterChangeHandler = (filter) => {
    setActivePolicyFilter(filter)
    setPaginationParams({ page: 1 })
  }

  useEffect(() => {
    setIsOpenBenefitModal(null)
    setPaginationParams({ page: 1 })
    setActivePolicyFilter('')

    return () => {
      dispatch(policyActions.resetReduxPolicy())
      dispatch(agencyActions.resetReduxState())
    }
  }, [
    isAgency
  ])

  useEffect(() => {
    dispatch(policyActions.clearPolicyRedux(['data']))
    dispatch(agencyActions.resetReduxState(['agencyPolicyList']))
    setPaginationParams({ page: 1 })
  }, [activePolicyFilter])

  useEffect(() => {
    const pageSize = 9
    const offset = (page - 1) * 9
    const limit = 9

    if (isAgency) {
      dispatch(agencyActions.getAgencyPolicyList({
        query: {
          offset,
          coverageStatus: activePolicyFilter,
          page,
          limit,
          pageSize
        }
      }
      ))
    } else {
      dispatch(policyActions.getPolicyList({
        offset,
        page,
        limit,
        coverage: activePolicyFilter
      }))
    }
    return () => {
      dispatch(policyActions.clearPolicyRedux(['data']))
      dispatch(agencyActions.resetReduxState(['agencyPolicyList']))
    }
  }, [
    page,
    activePolicyFilter,
    isAgency
  ])

  const renderPolicyList = () => {
    if (isPolicyListError) return <EmptyPolicyClaimListCard />
    if (isLoading === false && policyList?.length === 0) return <EmptyPolicyClaimListCard />
  }

  const tabs = () => {
    if (isAgency) {
      return AgencyTabs.map(({ title, filter, mobileTitle }) => ({ filter, title: isMobile ? mobileTitle : title }))
    }
    return PolicyTabs.map(({ title, filter, mobileTitle }) => ({ filter, title: isMobile ? mobileTitle : title }))
  }

  return (
    <Wrapper data-testid='policy-list'>
      <ScrollTabs
        selectedTag={activePolicyFilter}
        onTagClickHandler={onFilterChangeHandler}
        tabs={tabs()}
      />
      <PolicyListContainer>
        {renderPolicyList()}
        {
          Array.isArray(policyList)
            ? (
              policyList.map((pol) => {
                const {
                  logo,
                  packageCode,
                  product,
                  partner,
                  internalId,
                  applicationNo,
                  packageName,
                  mainDetails,
                  productDisplayName,
                  additionalProtection,
                  insuranceprovider,
                  isPolicyActive,
                  policyText,
                  isFamilyPolicy,
                  isAsdpFerryTravelPolicy
                } = isAgency
                  ? sanitizeAgencyPolicyListDetails(pol, intl)
                  : sanitizeB2CPolicyListDetails(pol, intl)
                const benefitQueryParams = {
                  applicationNo,
                  internalId,
                  packageCode,
                  product,
                  partner,
                  additionalProtection,
                  insuranceprovider,
                  isFamilyPolicy,
                  isAsdpFerryTravelPolicy
                }
                return (
                  <PolicyCard
                    logo={logo}
                    key={applicationNo}
                    policyText={policyText}
                    mainDetails={mainDetails}
                    headerTitle={packageName}
                    isPolicyActive={isPolicyActive}
                    headerSubTitle={productDisplayName}
                    leftSideButtonText={LANG_STRINGS.raiseClaim}
                    leftSideButtonClickHandler={(e) => openBenefitModal(e, benefitQueryParams)}
                    rightSideButtonClickHandler={(e) => goToPolicyDetailPage(e, internalId)}
                    rightSideFooterButtonText={LANG_STRINGS.detail}
                  />
                )
              })
            )
            : null}
        {isLoading
          ? (
            <Center>
              <Loader />
            </Center>
          )
          : null
        }
        {
          isOpenBenefitModal
            ? (
              <BenefitList
                isAgency={isAgency}
                closeBenefitModalPolicyList={closeBenefitModal}
                benefitQueryParams={isOpenBenefitModal.benefitQueryParams}
              />
            )
            : null
        }
      </PolicyListContainer>
      {
        (isLoading || (!get(policyMetaData, 'total_records', 0)))
          ? null
          : <Pagination
            pageSize={9}
            totalRecords={Number(get(policyMetaData, 'total_records', 0))}
            currPage={page}
            currPageHandler={paginationHandler}
          />
      }
    </Wrapper>
  )
}

export default PolicyList
