import { useLocation } from 'react-router'
import queryString from 'query-string'
import { tabKeyMap } from '../../constants'
import { useSelector } from 'react-redux'
import get from 'lodash/get'
import { isAgencyUser, isB2CUser } from '../../helpers/utility'
import PolicyList from '../PolicyList'
import ClaimList from '../ClaimList/claimList'

function Home () {
  const location = useLocation()
  const state = useSelector(state => state.User)
  const serviceList = get(state, 'details.services', [])

  const { source } = queryString.parse(location.search)

  const component = <span data-testid='no-render' />

  if (source === tabKeyMap.polis) return <PolicyList />
  if (source === tabKeyMap.claim) return <ClaimList />
  if (source === tabKeyMap.agencyPolis) return <PolicyList isAgency />
  if (source === tabKeyMap.agencyClaim) return <ClaimList isAgency />

  if (isB2CUser(serviceList)) return <PolicyList />
  if (isAgencyUser(serviceList)) return <PolicyList isAgency />

  return component
}

export default Home
